// SEO keyword ledger — single source of truth for titles, H1s, copy and the
// admin keyword tracker (see keyword-progress.functions.ts).
//
// Volumes/KDI from Semrush (database: tr), refreshed Jun 2026. Ordered within
// each tier by ascending difficulty so we always work the easiest unranked
// term next. Backward-compatible exports kept: TIER1_KEYWORDS, TIER2_KEYWORDS,
// ALL_KEYWORDS, KeywordEntry.

export type KeywordIntent = "local" | "transactional" | "informational";

// Topical cluster — groups keywords by the service/page family they feed.
export type KeywordCluster =
  | "su-kacagi"
  | "tikaniklik"
  | "kombi"
  | "petek"
  | "dogalgaz"
  | "kanal"
  | "tesisatci"
  | "acil"
  | "banyo-vitrifiye"
  | "musluk-batarya"
  | "hidrofor";

// Lifecycle status for the keyword (manually curated; GSC drives live ranking).
export type KeywordStatusFlag = "ranking" | "building" | "planned";

export type KeywordEntry = {
  keyword: string;
  volume: number; // monthly searches (TR)
  kdi: number; // 0–100 keyword difficulty
  intent: KeywordIntent;
  target: string; // destination path pattern
  cluster: KeywordCluster;
  status: KeywordStatusFlag;
};

